effect.shader:
float canal(vec2 uv, vec2 c, float esc, int k, int n) {
    float s = 0.0;
    for (int i = 0; i <= 48; i++) {
        if (i > n) break;
        float t = (float(i)/float(n) - 0.5) * esc;
        vec2 dir = normalize(uv - c + vec2(1e-5));
        vec2 perp = vec2(-dir.y, dir.x);
        s += texture(inputImg, uv + perp * t).rgb[k];
    }
    return s / float(n + 1);
}

void main() {
    vec4 o = texture(inputImg, acScreenNorm);
    if (strength <= 0.0) { fragColor = o; return; }
    int n = clamp(int(samples), 4, 48);
    float r = canal(acScreenNorm, center, strength * (1.0 + chroma), 0, n);
    float g = canal(acScreenNorm, center, strength,                    1, n);
    float b = canal(acScreenNorm, center, strength * (1.0 - chroma), 2, n);
    fragColor = vec4(r, g, b, o.a);
}
